-- Operations case and knowledge schema. Generated by go run ./cmd/ops-schema.
CREATE TABLE IF NOT EXISTS `ops_case` (`id` integer PRIMARY KEY AUTOINCREMENT,`group_id` integer NOT NULL,`severity` integer,`title` varchar(255) NOT NULL,`state` varchar(24) NOT NULL,`wait_reason` varchar(64) NOT NULL DEFAULT "",`owner_id` integer NOT NULL DEFAULT 0,`target_ident` varchar(255) NOT NULL DEFAULT "",`datasource_id` integer NOT NULL DEFAULT 0,`rule_id` integer NOT NULL DEFAULT 0,`context` TEXT,`knowledge_version_id` integer NOT NULL DEFAULT 0,`plan_id` integer NOT NULL DEFAULT 0,`revision` integer NOT NULL DEFAULT 1,`generation` integer NOT NULL DEFAULT 1,`close_type` varchar(40) NOT NULL DEFAULT "",`summary` text,`followup` text,`created_by` integer,`created_at` integer,`updated_at` integer,`closed_at` integer);
CREATE INDEX IF NOT EXISTS `idx_ops_case_created_at` ON `ops_case`(`created_at`);
CREATE INDEX IF NOT EXISTS `idx_ops_case_owner_id` ON `ops_case`(`owner_id`);
CREATE INDEX IF NOT EXISTS `idx_ops_case_group_state` ON `ops_case`(`group_id`,`state`);
CREATE TABLE IF NOT EXISTS `ops_episode` (`id` integer PRIMARY KEY AUTOINCREMENT,`case_id` integer NOT NULL,`group_id` integer NOT NULL,`incident_id` varchar(64) NOT NULL,`sequence` integer,`recovered` numeric,`snapshot` TEXT,`updated_at` integer,CONSTRAINT `uni_ops_episode_incident_id` UNIQUE (`incident_id`));
CREATE INDEX IF NOT EXISTS `idx_ops_episode_group_id` ON `ops_episode`(`group_id`);
CREATE INDEX IF NOT EXISTS `idx_ops_episode_case_id` ON `ops_episode`(`case_id`);
CREATE TABLE IF NOT EXISTS `ops_inbox` (`id` integer PRIMARY KEY AUTOINCREMENT,`dispatch_id` varchar(64) NOT NULL,`incident_id` varchar(64) NOT NULL,`case_id` integer NOT NULL,`created_at` integer,CONSTRAINT `uni_ops_inbox_dispatch_id` UNIQUE (`dispatch_id`));
CREATE INDEX IF NOT EXISTS `idx_ops_inbox_incident_id` ON `ops_inbox`(`incident_id`);
CREATE INDEX IF NOT EXISTS `idx_ops_inbox_case_id` ON `ops_inbox`(`case_id`);
CREATE TABLE IF NOT EXISTS `ops_evidence` (`id` integer PRIMARY KEY AUTOINCREMENT,`case_id` integer NOT NULL,`generation` integer,`kind` varchar(40) NOT NULL,`source` varchar(255) NOT NULL,`status` varchar(24) NOT NULL,`observed_at` integer,`window_start` integer,`window_end` integer,`collected_at` integer,`payload` TEXT,`sha256` varchar(64) NOT NULL,`created_by` integer);
CREATE INDEX IF NOT EXISTS `idx_ops_evidence_case_id` ON `ops_evidence`(`case_id`);
CREATE TABLE IF NOT EXISTS `ops_step` (`plan_id` integer NOT NULL DEFAULT 0,`id` integer PRIMARY KEY AUTOINCREMENT,`case_id` integer NOT NULL,`generation` integer,`version_id` integer,`step_key` varchar(64) NOT NULL,`state` varchar(24) NOT NULL,`evidence_ids` TEXT,`note` text,`created_by` integer,`created_at` integer);
CREATE INDEX IF NOT EXISTS `idx_ops_step_case_id` ON `ops_step`(`case_id`);
CREATE TABLE IF NOT EXISTS `ops_audit` (`id` integer PRIMARY KEY AUTOINCREMENT,`case_id` integer NOT NULL,`actor_id` integer,`action` varchar(64) NOT NULL,`detail` TEXT,`created_at` integer);
CREATE INDEX IF NOT EXISTS `idx_ops_audit_case_id` ON `ops_audit`(`case_id`);
CREATE TABLE IF NOT EXISTS `ops_action` (`plan_id` integer NOT NULL DEFAULT 0,`id` integer PRIMARY KEY AUTOINCREMENT,`case_id` integer NOT NULL,`generation` integer,`version_id` integer,`kind` varchar(32) NOT NULL,`state` varchar(24) NOT NULL,`operation_key` varchar(64) NOT NULL,`baseline` varchar(64) NOT NULL,`payload` TEXT,`result` TEXT,`proposed_by` integer,`approved_by` integer,`expires_at` integer,`created_at` integer,`updated_at` integer,CONSTRAINT `uni_ops_action_operation_key` UNIQUE (`operation_key`));
CREATE INDEX IF NOT EXISTS `idx_ops_action_state` ON `ops_action`(`state`);
CREATE INDEX IF NOT EXISTS `idx_ops_action_case_id` ON `ops_action`(`case_id`);
CREATE TABLE IF NOT EXISTS `ops_verification` (`plan_id` integer NOT NULL DEFAULT 0,`id` integer PRIMARY KEY AUTOINCREMENT,`case_id` integer NOT NULL,`generation` integer,`version_id` integer,`check_key` varchar(64) NOT NULL,`state` varchar(24) NOT NULL,`reason` text,`evidence_ids` TEXT,`confirmed_by` integer,`created_at` integer);
CREATE INDEX IF NOT EXISTS `idx_ops_verification_case_id` ON `ops_verification`(`case_id`);
CREATE TABLE IF NOT EXISTS `ops_run` (`id` integer PRIMARY KEY AUTOINCREMENT,`case_id` integer NOT NULL,`active_case_id` integer,`user_id` integer,`state` varchar(24) NOT NULL,`fence` integer NOT NULL DEFAULT 0,`lease_until` integer,`next_run_at` integer,`attempts` integer,`mode` varchar(24) NOT NULL,`result` text,`created_at` integer,`updated_at` integer,CONSTRAINT `uni_ops_run_active_case_id` UNIQUE (`active_case_id`));
CREATE INDEX IF NOT EXISTS `idx_ops_run_state` ON `ops_run`(`state`);
CREATE INDEX IF NOT EXISTS `idx_ops_run_case_id` ON `ops_run`(`case_id`);
CREATE TABLE IF NOT EXISTS `ops_policy` (`id` integer PRIMARY KEY AUTOINCREMENT,`group_id` integer NOT NULL,`enabled` numeric,`service_user_id` integer,`auto_investigate` numeric,`rule_ids` TEXT,`revision` integer NOT NULL DEFAULT 1,`scan_at` integer,`scan_id` integer,`reconcile_at` integer,`health` varchar(255),`gap_since` integer,CONSTRAINT `uni_ops_policy_group_id` UNIQUE (`group_id`));
CREATE TABLE IF NOT EXISTS `ops_plan` (`id` integer PRIMARY KEY AUTOINCREMENT,`case_id` integer NOT NULL,`sequence` integer NOT NULL,`title` varchar(255) NOT NULL,`scope` text,`rationale` text,`payload` TEXT,`evidence_ids` TEXT,`sha256` varchar(64) NOT NULL,`generation` integer,`evidence_anchor` integer,`confirmed_generation` integer,`state` varchar(24) NOT NULL,`created_by` integer,`created_at` integer,`confirmed_by` integer,`confirmed_at` integer,`decision_note` text);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_ops_plan_case_sequence` ON `ops_plan`(`case_id`,`sequence`);
CREATE TABLE IF NOT EXISTS `ops_knowledge` (`id` integer PRIMARY KEY AUTOINCREMENT,`group_id` integer NOT NULL,`title` varchar(255) NOT NULL,`draft` TEXT,`revision` integer NOT NULL DEFAULT 1,`current_version_id` integer NOT NULL DEFAULT 0,`created_by` integer,`updated_by` integer,`updated_at` integer);
CREATE INDEX IF NOT EXISTS `idx_ops_knowledge_group_id` ON `ops_knowledge`(`group_id`);
CREATE TABLE IF NOT EXISTS `ops_knowledge_version` (`id` integer PRIMARY KEY AUTOINCREMENT,`item_id` integer NOT NULL,`group_id` integer NOT NULL,`sequence` integer NOT NULL,`title` varchar(255) NOT NULL,`payload` TEXT,`sha256` varchar(64) NOT NULL,`published_by` integer,`published_at` integer,`withdrawn_at` integer,`withdraw_reason` text);
CREATE INDEX IF NOT EXISTS `idx_ops_knowledge_version_group_id` ON `ops_knowledge_version`(`group_id`);
CREATE UNIQUE INDEX IF NOT EXISTS `idx_ops_knowledge_sequence` ON `ops_knowledge_version`(`item_id`,`sequence`);
CREATE TABLE IF NOT EXISTS `ops_knowledge_source` (`id` integer PRIMARY KEY AUTOINCREMENT,`group_id` integer NOT NULL,`name` varchar(255) NOT NULL,`media_type` varchar(120) NOT NULL,`storage_key` varchar(64) NOT NULL,`sha256` varchar(64) NOT NULL,`size` integer,`description` text,`created_by` integer,`created_at` integer,CONSTRAINT `uni_ops_knowledge_source_storage_key` UNIQUE (`storage_key`));
CREATE INDEX IF NOT EXISTS `idx_ops_knowledge_source_group_id` ON `ops_knowledge_source`(`group_id`);
